Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PNADEC.
Import PMS.
Import NEM.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation AQ := PnLayoutQS.QADDR_S.
Abbreviation AE := NemLayoutS.NEADDR_S.
Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis OPN : PQAS.opnew_spec_n RSEGS AD L HI PQAS.NREQ.
Hypothesis OPD : PMS.opdel_spec L HI.
#[local] Abbreviation ae_at := (NEM.ae_at RSEGS AD AE L PMSP.T3 PMSP.T4 (qa_vp_adaptor PnLayoutQS.QADDR_S)).
(* [comment removed for export] *)
Hypothesis VUE : NECS.v_uint64_spec RSEGS AD AQ AE L HI NESK.PME.
Hypothesis VIE : NECS.v_int64_spec RSEGS AD AQ AE L HI NESK.PME.
Hypothesis VKE : NECS.v_key_spec RSEGS AD AQ AE L HI NESK.PME.

Section Ctx.
Variables (M0 : word -> option byte) (K : TSet) (LBX : list (Z * Z)) (S oa ov osk oec : Z).
Hypothesis CX : PNADVK.ctx_ok L M0 K LBX S oa ov.
Hypothesis CXO : S <= osk /\ osk + 24 <= hl_sptop L /\ osk mod 8 = 0 /\ S <= oec /\ oec + 16 <= hl_sptop L /\ oec mod 8 = 0 /\ oec + 16 <= oa /\ ov + 56 <= osk /\ ov mod 8 = 0.
Let KL := PMKS.klayout_S L LY.
Let cm := PNADVK.cm L M0 LBX S oa ov osk oec.
Let world := PNADVK.world ov.

(* [comment removed for export] *)
Lemma ENC_SLOT (pc h : Z) (args : NECS.eargs -> bvmap 5 word -> (word -> option byte) -> Z -> Z -> Z -> list (Z * Z) -> Prop)
      (pre : NECS.eargs -> enc -> NESK.sink -> Prop) (step : NECS.eargs -> enc -> NESK.sink -> bool -> enc -> NESK.sink -> bool -> Prop)
      (SPEC : NECS.eslot_spec RSEGS AD AQ AE L HI NESK.PME pc h args pre step) (Hh : 1 <= h <= 7) (sp' : Z)
      (ea : NECS.eargs) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (st : aest) (cr : credit) (ra cat : Z) (b e : bool) :
  S - 28672 + PMSP.pm_scr h <= sp' -> sp' <= S -> sp' mod 16 = 0 ->
  getr R (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R (reg 2) = Z_to_bv 64 sp' -> getr R (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R (reg 4) = Z_to_bv 64 (pa_tp AD) ->
  getr R (reg 10) = Z_to_bv 64 ov -> args ea R M (sp') ov oec (PQM.aown (ae_a st) ++ LBX) ->
  cm M -> world M -> ae_at M oa ov osk st -> PQM.adaptor_ok (ae_a st) -> NEM.ec_state RSEGS AD M oec b cat -> PQST.err_ok RSEGS AD AQ M e ->
  pre ea (ae_e st) (ae_s st) ->
  PMSP.credit_le (pot_ae L st) cr -> PMSP.model_ok model -> hi_heap HI (aeown st ++ LBX) cr M (m_vmmaps model) ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (en' : enc) (k' : NESK.sink) (b' e' : bool) (cr' : credit),
      let st' := AEST (ae_a st) (ae_kbb st) en' k' in
      regs_preserved R R' -> cm M' -> world M' ->
      L5C.hpres L (PQM.aown (ae_a st) ++ LBX) (sp') (PMSP.pm_scr h) (NECS.W_enc AD ov osk oec) M M' ->
      (forall a m, sp' <= a -> a + m <= 2 ^ 64 -> (a + m <= ov + 24 \/ ov + 56 <= a) -> (a + m <= osk \/ osk + 24 <= a) -> (a + m <= oec \/ oec + 16 <= a) -> L5C.agree_on M M' a m) ->
      ae_at M' oa ov osk st' -> NEM.ec_state RSEGS AD M' oec b' cat -> PQST.err_ok RSEGS AD AQ M' e' ->
      (b = true -> b' = true) -> (e = true -> e' = true) ->
      step ea (ae_e st) (ae_s st) b en' k' b' ->
      PMSP.credit_keep cr cr' (pot_ae L st) (pot_ae L st') ->
      model_but_vm model model' -> hi_heap HI (aeown st' ++ LBX) cr' M' (m_vmmaps model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' ra M' model') K) ->
