(* [comment removed for export] *)
Lemma ENC_I64 (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (st : aest) (cr : credit) (ra v cat : Z) (b e : bool) :
  getr R (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R (reg 2) = Z_to_bv 64 (S - 64) -> getr R (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R (reg 4) = Z_to_bv 64 (pa_tp AD) ->
  getr R (reg 10) = Z_to_bv 64 ov -> getr R (reg 11) = Z_to_bv 64 v -> 0 <= v < 2 ^ 64 -> getr R (reg 12) = Z_to_bv 64 TAG_NONE ->
  getr R (reg 14) = Z_to_bv 64 oec ->
  cm M -> world M -> ae_at M oa ov osk st -> ae_ok st -> NEM.ec_state RSEGS AD M oec b cat -> PQST.err_ok RSEGS AD AQ M e ->
  zsize st + w_i64 (NECS.sval v) <= NESK.SMZ ->
  PMSP.credit_le (pot_ae L st) cr -> PMSP.model_ok model -> hi_heap HI (aeown st ++ LBX) cr M (m_vmmaps model) ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (en' : enc) (k' : NESK.sink) (b' e' : bool) (cr' : credit),
      let st' := AEST (ae_a st) (ae_kbb st) en' k' in
      regs_preserved R R' -> cm M' -> world M' ->
      L5C.hpres L (PQM.aown (ae_a st) ++ LBX) (S - 64) (PMSP.pm_scr NECS.ENC_H) (NECS.W_enc AD ov osk oec) M M' ->
      (forall a m, S - 64 <= a -> a + m <= 2 ^ 64 -> (a + m <= ov + 24 \/ ov + 56 <= a) -> (a + m <= osk \/ osk + 24 <= a) -> (a + m <= oec \/ oec + 16 <= a) -> L5C.agree_on M M' a m) ->
      ae_at M' oa ov osk st' -> ae_ok st' -> NEM.ec_state RSEGS AD M' oec b' cat -> PQST.err_ok RSEGS AD AQ M' e' ->
      (b = true -> b' = true) -> (e = true -> e' = true) ->
      NECS.step_i64 (NECS.EA TAG_NONE v 0 []) (ae_e st) (ae_s st) b en' k' b' ->
      PMSP.credit_keep cr cr' (pot_ae L st) (pot_ae L st') ->
      model_but_vm model model' -> hi_heap HI (aeown st' ++ LBX) cr' M' (m_vmmaps model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' ra M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R (ne_int64 AE) M model) K.
